private theorem strict_sizes (p : α) (xs : List α) (hp : p ∈ xs) :
    (Partition.partitionRun p xs).1.1.length < xs.length ∧
      (Partition.partitionRun p xs).1.2.2.length < xs.length

private theorem medians_positive (d : Nat) (xs : List α)
    (hd : 2 ≤ d) (hx : 0 < xs.length) :
    0 < (chunkMediansRun d xs).1.length

private theorem medians_shorter (d : Nat) (xs : List α)
    (hd : 2 ≤ d) (hx : 1 < xs.length) :
    (chunkMediansRun d xs).1.length < xs.length

private theorem first_partition :
    partition3 12 (List.range 21) =
      (List.range 12, [12], [13, 14, 15, 16, 17, 18, 19, 20])

private theorem first_pivot_observation :
    (selectRun ((((List.range 21).length ⌈/⌉ 5) - 1) / 2)
      (chunkMediansRun 5 (List.range 21)).1).1 = some 12
